    (73429, '50e5e380-1f89-4fa3-88de-e6ad35241316'::uuid, 'artifact', NULL, 'g0-vlm-kind-rollback:73429', 'rollback of G0b: image_kind on 73429 returned to NULL (was ''artifact'')', '[{"source": "remediation_change_log (the row this undoes)", "url": "remediation_change_log.row_pk=73429", "quote": "run_stamp=''gallery-verdicts-persist-07817ee0'' wrote image_kind=''artifact'' where it was NULL"}, {"source": "the verdict this restores NULL over", "url": "output/remediation/vlm_pilot/REJECTED_KINDS.jsonl", "quote": "PROVEN image_id=73429 reason=''kind=artifact''"}, {"source": "the design rule being restored", "url": "migrations/0019_wiki_images_image_kind.sql", "quote": "NULL means no verdict has been recorded; ''unknown'' means a model looked and could not decide - rolling back restores the former, not the latter"}]'::jsonb),
    (73430, '50e5e380-1f89-4fa3-88de-e6ad35241316'::uuid, 'map_or_document', NULL, 'g0-vlm-kind-rollback:73430', 'rollback of G0b: image_kind on 73430 returned to NULL (was ''map_or_document'')', '[{"source": "remediation_change_log (the row this undoes)", "url": "remediation_change_log.row_pk=73430", "quote": "run_stamp=''gallery-verdicts-persist-07817ee0'' wrote image_kind=''map_or_document'' where it was NULL"}, {"source": "the verdict this restores NULL over", "url": "output/remediation/vlm_pilot/REJECTED_KINDS.jsonl", "quote": "PROVEN image_id=73430 reason=''kind=map_or_document''"}, {"source": "the design rule being restored", "url": "migrations/0019_wiki_images_image_kind.sql", "quote": "NULL means no verdict has been recorded; ''unknown'' means a model looked and could not decide - rolling back restores the former, not the latter"}]'::jsonb);

DO $$
DECLARE
    bad      integer;
    moved    integer := 0;
    expected integer := 30;
    r        RECORD;
BEGIN

    -- scope guard 1: every planned row exists
    SELECT count(*) INTO bad FROM _kind_plan p
      LEFT JOIN wiki_images w ON w.id = p.image_id WHERE w.id IS NULL;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0b rollback image_kind: % planned row(s) do not exist', bad;
    END IF;

    -- scope guard 2: every planned row belongs to a curated site.
    -- The source name is passed as a RAISE argument, not embedded in the message: a literal
    -- 'ancient_nerds' inside a single-quoted RAISE message terminates the string and the whole
    -- statement fails to parse (measured - the rehearsal caught exactly that).
    SELECT count(*) INTO bad
      FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id
      JOIN unified_sites s ON s.id = w.site_id
     WHERE s.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0b rollback image_kind: % planned row(s) are outside source_id %', bad, 'ancient_nerds';
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names. NULL-safe:
    -- `image_kind = NULL` is NULL, not true, and would match nothing.
    SELECT count(*) INTO bad
      FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id
     WHERE w.image_kind IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0b rollback image_kind: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    FOR r IN SELECT * FROM _kind_plan ORDER BY image_id LOOP
        moved := moved + apply_remediation_change(
            'wiki_images', 'image_kind', 'id', r.image_id::text,
            r.old_value, r.new_value,
            'G0/vlm-kind', 'gallery-verdicts-persist-07817ee0-rollback', r.change_key, 'authoritative',
            r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'G0b rollback: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row is back to NULL, the pre-state this reversal restores
    SELECT count(*) INTO bad
      FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id
     WHERE w.image_kind IS NOT NULL;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0b rollback: % row(s) are still not NULL', bad;
    END IF;

    -- invariant 2: the reversal's journal and the data agree, row for row, in both directions.
    -- The counts agreeing is not enough: the journal must name the same rows, record the value it
    -- undid as old_value, and record the NULL it restored as new_value.
    SELECT count(*) INTO bad
      FROM _kind_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.image_id::text AND l.table_name = 'wiki_images'
       AND l.column_name = 'image_kind'
       AND l.run_stamp = 'gallery-verdicts-persist-07817ee0-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS NOT NULL
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0b rollback: % planned row(s) disagree with the reversal journal', bad;
    END IF;

    -- invariant 3: the reversal stamp journalled nothing outside wiki_images.image_kind
    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'gallery-verdicts-persist-07817ee0-rollback'
       AND (l.table_name <> 'wiki_images' OR l.column_name <> 'image_kind');
    IF bad > 0 THEN
        RAISE EXCEPTION
            'G0b rollback: this run stamp journalled % row(s) outside wiki_images.image_kind',
            bad;
    END IF;
END $$;

SELECT 'planned rows restored to NULL', count(*)::text
  FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id WHERE w.image_kind IS NULL;
SELECT 'journal rows for the rollback', count(*)::text FROM remediation_change_log
 WHERE run_stamp = 'gallery-verdicts-persist-07817ee0-rollback';
COMMIT;
